const calDateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function parseTaskDue(due){const now=new Date();if(due==='Today')return dateKey(now);if(due==='Tomorrow'){const d=new Date(now);d.setDate(d.getDate()+1);return dateKey(d)}const m=String(due||'').match(/(\d{1,2})\s+([A-Za-z]{3})/);if(!m)return null;const months={Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};const d=new Date(now.getFullYear(),months[m[2]],Number(m[1]));return dateKey(d)}
function calendarEvents(){
 const taskEvents=state.tasks.map(t=>({date:parseTaskDue(t.due),title:t.name,type:'Task',meta:t.status})).filter(x=>x.date);
 const leaveEvents=state.leave.filter(x=>x.status==='Approved'||x.status==='Pending').flatMap(x=>{const out=[];let d=new Date((x.fromDate||x.date)+'T00:00:00'),end=new Date((x.toDate||x.date)+'T00:00:00');while(d<=end){out.push({date:calDateKey(d),title:`${x.type} (${x.status})`,type:'Leave',meta:x.reason||''});d.setDate(d.getDate()+1)}return out});
 const meetings=[{date:dateKey(),title:'Daily work review',type:'Meeting',meta:'05:00 PM'}];
 return [...taskEvents,...leaveEvents,...calendarHolidays,...meetings];
}
function employeeCalendar(){
 const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),startDay=first.getDay(),days=last.getDate();
 const all=calendarEvents(), filtered=calendarFilter==='All'?all:all.filter(e=>e.type===calendarFilter);
 const monthName=calendarCursor.toLocaleDateString('en-IN',{month:'long',year:'numeric'});
 const cells=[];for(let i=0;i<startDay;i++){const d=new Date(y,m,1-startDay+i);cells.push({d,muted:true})}for(let day=1;day<=days;day++)cells.push({d:new Date(y,m,day),muted:false});while(cells.length%7) {const n=cells.length-startDay-days+1;cells.push({d:new Date(y,m+1,n),muted:true})}
 const upcoming=all.filter(e=>new Date(e.date+'T00:00:00')>=new Date(new Date().toDateString())).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6);
 return `<section class="calendar-page"><div class="calendar-toolbar card"><div><span class="eyebrow-purple">EMPLOYEE SCHEDULE</span><h2>${monthName}</h2><p>Tasks, meetings, holidays and approved leave — all in one place.</p></div><div class="calendar-nav"><button class="btn ghost" data-cal-nav="prev">‹</button><button class="btn secondary" data-cal-nav="today">Today</button><button class="btn ghost" data-cal-nav="next">›</button></div></div><div class="calendar-filterbar">${['All','Task','Meeting','Holiday','Leave'].map(f=>`<button class="calendar-filter ${calendarFilter===f?'active':''}" data-cal-filter="${f}">${f}</button>`).join('')}</div><div class="calendar-layout"><section class="card calendar-card"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid">${cells.map(({d,muted})=>{const key=calDateKey(d),ev=filtered.filter(x=>x.date===key),today=key===dateKey();return `<div class="calendar-day ${muted?'muted':''} ${today?'today':''}"><div class="calendar-date"><span>${d.getDate()}</span>${today?'<b>Today</b>':''}</div><div class="calendar-events">${ev.slice(0,3).map(x=>`<button class="cal-event ${x.type.toLowerCase()}" title="${x.title}"><span></span>${x.title}</button>`).join('')}${ev.length>3?`<small>+${ev.length-3} more</small>`:''}</div></div>`}).join('')}</div></section><aside class="card calendar-side-panel"><div class="section-title"><div><h2>Upcoming</h2><p class="section-sub">Your next dates and deadlines</p></div></div><div class="upcoming-list">${upcoming.length?upcoming.map(e=>`<div class="upcoming-item"><div class="upcoming-date"><b>${new Date(e.date+'T00:00:00').getDate()}</b><span>${new Date(e.date+'T00:00:00').toLocaleDateString('en-IN',{month:'short'})}</span></div><div><span class="event-type ${e.type.toLowerCase()}">${e.type}</span><h4>${e.title}</h4><p>${e.meta||fmtRecordDate(e.date)}</p></div></div>`).join(''):'<div class="leave-empty"><span>□</span><b>No upcoming items</b><p>New tasks and holidays will appear here.</p></div>'}</div><div class="calendar-legend"><h3>Legend</h3>${[['task','Task'],['meeting','Meeting'],['holiday','Holiday'],['leave','Leave']].map(x=>`<span><i class="${x[0]}"></i>${x[1]}</span>`).join('')}</div></aside></div></section>`
}

