function openPayslipModal(id){const p=state.payslips.find(x=>x.id===id);if(!p)return;closePayslipModal();const el=document.createElement('div');el.id='payslipModal';el.className='payslip-modal-backdrop';el.innerHTML=`<div class="payslip-modal"><button class="payslip-modal-close" data-close-payslip>×</button><div class="payslip-modal-toolbar"><div><span class="eyebrow-purple">SALARY STATEMENT</span><h2>${p.month}</h2></div><div><button class="btn ghost" data-payslip-print="${p.id}">Print</button><button class="btn" data-payslip-download="${p.id}">Download</button></div></div>${payslipDocument(p)}</div>`;document.body.appendChild(el);document.body.classList.add('modal-open')}
function printPayslip(id){const p=state.payslips.find(x=>x.id===id);if(!p)return;const w=window.open('','_blank','width=920,height=850');w.document.write(`<html><head><title>${p.month} Payslip</title><style>${payslipPrintCss()}</style></head><body>${payslipDocument(p)}</body></html>`);w.document.close();setTimeout(()=>{w.focus();w.print()},250)}
function payslipPrintCss(){return `body{font-family:Arial,sans-serif;background:#f5f1f8;padding:30px;color:#171124}.salary-slip{max-width:820px;margin:auto;background:#fff;padding:32px;border:1px solid #ddd;border-radius:18px}.slip-head,.slip-employee,.slip-tables,.slip-foot{display:flex;justify-content:space-between;gap:20px}.slip-head{border-bottom:2px solid #6d28d9;padding-bottom:20px}.slip-brand{font-size:22px}.slip-brand span{color:#f59e0b}.slip-head>div:last-child{text-align:right}.slip-head span,.slip-head p,.slip-employee span,.slip-employee small,.slip-foot small{display:block;color:#756a80}.slip-employee{padding:22px 0;border-bottom:1px solid #ddd}.slip-employee>div{flex:1}.slip-employee b{display:block;margin:6px 0}.slip-tables{margin-top:24px}.slip-tables>div{width:50%;border:1px solid #ddd;border-radius:12px;padding:16px}.slip-tables h3{margin-top:0}.slip-tables div div,.slip-tables footer{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #eee}.slip-tables footer{border:0;margin-top:8px}.slip-net{text-align:center;margin:25px 0;padding:20px;background:#f4eaff;border-radius:14px}.slip-net span,.slip-net p{display:block;color:#6f6178}.slip-net strong{display:block;font-size:34px;margin:8px}.signature{text-align:right}.slip-note{text-align:center;font-size:11px;color:#888;margin-top:25px}@media print{body{background:#fff;padding:0}.salary-slip{border:0}}`}
function downloadPayslip(id){const p=state.payslips.find(x=>x.id===id);if(!p)return;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${p.month} Payslip</title><style>${payslipPrintCss()}</style></head><body>${payslipDocument(p)}</body></html>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download=`SBX-Payslip-${p.id}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Payslip downloaded')}

