function render(){const map={dashboard, tasks, attendance, leave,calendar:employeeCalendar,performance,rewards,payslips,notifications,profile};app.innerHTML=map[current]();tick();syncNotificationBadge();}
function tick(){const c=document.getElementById('clock');if(c)c.textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});const am=attendanceMeta();document.querySelectorAll('[data-live-worked]').forEach(el=>el.textContent=am.worked);document.querySelectorAll('[data-live-break]').forEach(el=>el.textContent=am.breakTime);}setInterval(tick,1000);today.textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short'});
document.addEventListener('click',e=>{const g=e.target.closest('[data-go]');if(g)go(g.dataset.go);const a=e.target.closest('[data-att]');if(a){const now=Date.now(),action=a.dataset.att;if(action==='checkin'){if(state.attendance==='in')return;state.attendance='in';state.break=false;state.checkInAt=now;state.attendanceDateKey=dateKey(now);state.breakStartedAt=null;state.totalBreakMs=0;state.lastWorkedMs=0;toast(`Checked in at ${fmtClock(now)}`)}if(action==='break'&&state.attendance==='in'&&!state.break){state.break=true;state.breakStartedAt=now;toast(`Break started at ${fmtClock(now)}`)}if(action==='endbreak'&&state.break){if(state.breakStartedAt)state.totalBreakMs=(state.totalBreakMs||0)+(now-state.breakStartedAt);state.break=false;state.breakStartedAt=null;toast('Break ended — work timer resumed')}if(action==='checkout'&&state.attendance==='in'){if(state.break&&state.breakStartedAt)state.totalBreakMs=(state.totalBreakMs||0)+(now-state.breakStartedAt);const checkInAt=state.checkInAt,workedMs=Math.max(0,now-checkInAt-(state.totalBreakMs||0)),record={dateKey:state.attendanceDateKey||dateKey(checkInAt),checkInAt,checkOutAt:now,totalBreakMs:state.totalBreakMs||0,workedMs,status:isLateCheckIn(checkInAt)?'Late':'Present'};state.attendanceRecords=state.attendanceRecords.filter(r=>r.dateKey!==record.dateKey);state.attendanceRecords.unshift(record);state.lastWorkedMs=workedMs;state.attendance='out';state.break=false;state.breakStartedAt=null;state.checkInAt=null;state.attendanceDateKey=null;toast(`Checked out · ${fmtDuration(workedMs)} recorded`)}save();render()}const filter=e.target.closest('[data-filter]');if(filter){taskFilter=filter.dataset.filter;render()}const open=e.target.closest('[data-open-task]');if(open)openTaskModal(open.dataset.openTask);if(e.target.matches('[data-close-task]')){e.preventDefault();closeTaskModal();return}if(e.target.matches('.task-modal-backdrop')){closeTaskModal();return}const closeReview=e.target.closest('[data-close-review]');if(closeReview){e.preventDefault();closeReviewStatus();return}const flow=e.target.closest('[data-task-flow]');if(flow){const x=state.tasks.find(z=>z.id==flow.dataset.taskFlow);if(x.status==='To Do'){x.status='In Progress';x.progress=Math.max(x.progress,10);x.timeSpent+=5;toast('Task started — now In Progress')}else if(x.status==='In Progress'){openTaskModal(x.id);return}else if(x.status==='Revision'){x.status='In Progress';toast('Revision task reopened')}else if(x.status==='Review'){showReviewStatus(x.id);return}else{openTaskModal(x.id);return}save();render();if(current==='tasks')openTaskModal(x.id)}const qp=e.target.closest('[data-quick-progress]');if(qp){const x=state.tasks.find(z=>z.id==qp.dataset.quickProgress);x.progress=Math.min(95,x.progress+10);x.timeSpent+=10;save();toast('Progress updated');render()}const submit=e.target.closest('[data-submit-review]');if(submit){const x=state.tasks.find(z=>z.id==submit.dataset.submitReview);if(x.completedChecks.length<x.checklist.length)return toast('Complete all checklist items first');x.status='Review';x.progress=100;x.comments.unshift({text:'Submitted for founder review',at:'Just now'});save();closeTaskModal();toast('Submitted for review');render()}const check=e.target.closest('[data-legacy-check-task]');if(check){}const range=e.target.closest('[data-progress-task]');if(range){const x=state.tasks.find(z=>z.id==range.dataset.progressTask);x.progress=Number(range.value);x.timeSpent+=5;save();openTaskModal(x.id)}const comment=e.target.closest('[data-add-comment]');if(comment){const x=state.tasks.find(z=>z.id==comment.dataset.addComment),input=document.getElementById('taskComment');if(!input.value.trim())return toast('Write an update first');x.comments.unshift({text:input.value.trim(),at:'Just now'});x.timeSpent+=5;save();toast('Update added');openTaskModal(x.id)}const calNav=e.target.closest('[data-cal-nav]');if(calNav){if(calNav.dataset.calNav==='prev')calendarCursor.setMonth(calendarCursor.getMonth()-1);if(calNav.dataset.calNav==='next')calendarCursor.setMonth(calendarCursor.getMonth()+1);if(calNav.dataset.calNav==='today'){calendarCursor=new Date();calendarCursor.setDate(1)}render();return}const calFilter=e.target.closest('[data-cal-filter]');if(calFilter){calendarFilter=calFilter.dataset.calFilter;render();return}const perfPeriod=e.target.closest('[data-performance-period]');if(perfPeriod){e.preventDefault();performancePeriod=perfPeriod.dataset.performancePeriod;localStorage.setItem('sbx_performance_period',performancePeriod);render();toast(`${performancePeriod} performance loaded`);return}if(e.target.id==='applyLeave'){const from=document.getElementById('leaveFromDate').value,to=document.getElementById('leaveToDate').value,reason=document.getElementById('leaveReason').value.trim(),type=document.getElementById('leaveType').value;if(!from||!to)return toast('Select both From and To dates');if(to<from)return toast('To date cannot be before From date');if(!reason)return toast('Add a reason for your leave');const days=leaveDayCount(from,to);state.leave.unshift({id:Date.now(),type,fromDate:from,toDate:to,date:from,days,reason,status:'Pending',submittedAt:new Date().toISOString()});save();toast(`${days}-day leave request sent`);render()}const rewardViewBtn=e.target.closest('[data-reward-view]');if(rewardViewBtn){rewardView=rewardViewBtn.dataset.rewardView;localStorage.setItem('sbx_reward_view',rewardView);render();return}const redeemBtn=e.target.closest('[data-reward-redeem]');if(redeemBtn){openRewardModal(redeemBtn.dataset.rewardRedeem);return}if(e.target.closest('[data-close-reward]')||e.target.classList.contains('reward-modal-backdrop')){closeRewardModal();return}const confirmReward=e.target.closest('[data-confirm-reward]');if(confirmReward){const r=rewardCatalog.find(x=>x.id===confirmReward.dataset.confirmReward);if(!r)return;if(state.points<r.points){toast('Not enough points');return}state.points-=r.points;state.redemptions.unshift({id:Date.now(),rewardId:r.id,rewardName:r.name,points:r.points,date:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),status:'Pending'});save();closeRewardModal();rewardView='requests';localStorage.setItem('sbx_reward_view',rewardView);toast('Redemption request sent for founder approval');render();return}const payFilter=e.target.closest('[data-payslip-filter]');if(payFilter){payslipStatusFilter=payFilter.dataset.payslipFilter;localStorage.setItem('sbx_payslip_filter',payslipStatusFilter);render();return}const payView=e.target.closest('[data-payslip-view]');if(payView){openPayslipModal(payView.dataset.payslipView);return}const payPrint=e.target.closest('[data-payslip-print]');if(payPrint){printPayslip(payPrint.dataset.payslipPrint);return}const payDownload=e.target.closest('[data-payslip-download]');if(payDownload){downloadPayslip(payDownload.dataset.payslipDownload);return}if(e.target.closest('[data-close-payslip]')||e.target.classList.contains('payslip-modal-backdrop')){closePayslipModal();return}const nf=e.target.closest('[data-notification-filter]');if(nf){notificationFilter=nf.dataset.notificationFilter;localStorage.setItem('sbx_notification_filter',notificationFilter);render();return}const nall=e.target.closest('[data-notification-read-all]');if(nall){state.notifications.forEach(n=>n.read=true);save();toast('All notifications marked as read');render();return}const nread=e.target.closest('[data-notification-read]');if(nread){const n=state.notifications.find(x=>x.id==nread.dataset.notificationRead);if(n){n.read=!n.read;save();render()}return}const ndel=e.target.closest('[data-notification-delete]');if(ndel){state.notifications=state.notifications.filter(x=>x.id!=ndel.dataset.notificationDelete);save();toast('Notification removed');render();return}const nopen=e.target.closest('[data-notification-open]');if(nopen){const n=state.notifications.find(x=>x.id==nopen.dataset.notificationOpen);if(n){n.read=true;save();go(n.link||'dashboard')}return}if(e.target.id==='saveProfile'){
 const p=state.profile;
 p.fullName=document.getElementById('pfFullName')?.value.trim()||p.fullName;
 p.email=document.getElementById('pfEmail')?.value.trim()||'';
 p.phone=document.getElementById('pfPhone')?.value.trim()||'';
 p.dob=document.getElementById('pfDob')?.value||'';
 p.address=document.getElementById('pfAddress')?.value.trim()||'';
 p.emergencyContact=document.getElementById('pfEmergency')?.value.trim()||'';
 p.bankName=document.getElementById('pfBank')?.value.trim()||'';
 const account=document.getElementById('pfAccount')?.value||'';p.accountLast4=(account.match(/\d{4}$/)||[''])[0];
 p.ifsc=document.getElementById('pfIfsc')?.value.trim().toUpperCase()||'';
 p.pan=document.getElementById('pfPan')?.value.trim().toUpperCase()||'';
 p.emailAlerts=!!document.getElementById('pfEmailAlerts')?.checked;
 p.desktopAlerts=!!document.getElementById('pfDesktopAlerts')?.checked;
 p.language=document.getElementById('pfLanguage')?.value||'English';save();toast('Profile changes saved');render();return
 }
 if(e.target.id==='profileAvatarBtn'){document.getElementById('profileAvatarInput')?.click();return}
 if(e.target.id==='resetProfile'){render();toast('Unsaved changes reset');return}
 if(e.target.id==='downloadProfile'){const p=state.profile,text=`SBX Rocket Employee Profile\n\nName: ${p.fullName}\nEmployee ID: ${p.employeeId}\nRole: ${p.role}\nDepartment: ${p.department}\nEmail: ${p.email}\nPhone: ${p.phone||'—'}\nManager: ${p.manager}\nJoining date: ${p.joiningDate}`;const blob=new Blob([text],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${p.employeeId}-profile.txt`;a.click();URL.revokeObjectURL(a.href);toast('Profile downloaded');return}
 if(e.target.id==='changePassword'){const next=prompt('Enter a new demo password (minimum 6 characters)');if(next&&next.length>=6)toast('Password updated for local preview');else if(next)toast('Password must be at least 6 characters');return}
});
document.addEventListener('change',e=>{if(e.target.id==='profileAvatarInput'&&e.target.files&&e.target.files[0]){const file=e.target.files[0];if(file.size>2*1024*1024)return toast('Image must be under 2 MB');const reader=new FileReader();reader.onload=()=>{state.profile.avatar=reader.result;save();render();toast('Profile photo updated')};reader.readAsDataURL(file);return}if(e.target.id==='leaveFromDate'||e.target.id==='leaveToDate'){const from=document.getElementById('leaveFromDate')?.value||'',toEl=document.getElementById('leaveToDate'),to=toEl?.value||'';if(e.target.id==='leaveFromDate'&&toEl){toEl.min=from||dateKey();if(to&&to<from)toEl.value=from}const days=leaveDayCount(from,toEl?.value||'');const output=document.getElementById('leaveDuration');if(output)output.textContent=days?`${days} day${days>1?'s':''}`:'Select dates'}});
